<script setup>
import { onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { listCases,assignCase } from '../../api/case';import { listAdmin } from '../../api/admin';import { text,tagType } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue';import { messageOf } from '../../utils/request'
const state=reactive({list:[],total:0,pageNum:1,pageSize:10,status:'PENDING_ASSIGNMENT',loading:false});const agents=ref([]);const open=ref(false);const current=ref({});const form=reactive({agentId:null,reason:''});const reassign=ref(false)
const load=async()=>{state.loading=true;try{const r=await listCases('/admin/cases',{pageNum:state.pageNum,pageSize:state.pageSize,status:state.status||undefined});state.list=r.data.list;state.total=r.data.total}finally{state.loading=false}};const show=(row)=>{current.value=row;reassign.value=row.status!=='PENDING_ASSIGNMENT';Object.assign(form,{agentId:null,reason:''});open.value=true};const save=async()=>{try{await assignCase(current.value.id,form,reassign.value);ElMessage.success('代理人分配成功');open.value=false;load()}catch(e){ElMessage.error(messageOf(e))}};onMounted(async()=>{agents.value=(await listAdmin('agents',{pageSize:100})).data.list;load()})
</script>
<template><div class="page"><PageHeader title="案件分配" description="分配或调整主办代理人，历史记录永久保留"/><div class="toolbar"><el-select v-model="state.status" placeholder="案件状态" clearable @change="load"><el-option label="待分配" value="PENDING_ASSIGNMENT"/><el-option label="办理中" value="PROCESSING"/></el-select></div><div class="table-wrap"><el-table v-loading="state.loading" :data="state.list"><el-table-column prop="caseNo" label="案件编号" width="160"/><el-table-column prop="caseName" label="案件名称" min-width="230"/><el-table-column label="类型" width="110"><template #default="{row}">{{text('caseType',row.caseType)}}</template></el-table-column><el-table-column prop="principalAgentId" label="当前代理人 ID" width="120"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="tagType(row.status)">{{text('caseStatus',row.status)}}</el-tag></template></el-table-column><el-table-column width="100"><template #default="{row}"><el-button link type="primary" @click="show(row)">{{row.status==='PENDING_ASSIGNMENT'?'分配':'调整'}}</el-button></template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/><el-dialog v-model="open" :title="reassign?'调整主办代理人':'分配主办代理人'" width="min(520px,94vw)"><p class="dialog-lead">{{current.caseName}}</p><el-form label-position="top"><el-form-item label="代理人"><el-select v-model="form.agentId" filterable><el-option v-for="a in agents" :key="a.id" :label="`${a.employeeNo} · ${a.professionalField||'代理人'}`" :value="a.id"/></el-select></el-form-item><el-form-item label="分配原因"><el-input v-model="form.reason" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="save">确认分配</el-button></template></el-dialog></div></template>
